    if not grid:
        return 0
    m, n = len(grid), len(grid[0])
    visited = [[False]*n for _ in range(m)]
    def dfs(i,j):
        stack = [(i,j)]
        while stack:
            x,y = stack.pop()
            if x<0 or x>=m or y<0 or y>=n:
                continue
            if visited[x][y] or grid[x][y]==0:
                continue
            visited[x][y]=True
            stack.extend([(x-1,y),(x+1,y),(x,y-1),(x,y+1)])
    count=0
    for i in range(m):
        for j in range(n):
            if not visited[i][j] and grid[i][j]==1:
                dfs(i,j)
                count+=1
    return count
