code:
def solve(grid):
    if not grid:
        return 0
    n = len(grid)
    m = max((len(row) for row in grid), default=0)
    visited = [[False]*m for _ in range(n)]
    def valid(i,j):
        return 0 <= i < n and 0 <= j < len(grid[i])
    def dfs(i,j):
        stack = [(i,j)]
        while stack:
            x,y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx,ny = x+dx, y+dy
                if valid(nx,ny) and not visited[nx][ny] and grid[nx][ny]==1:
                    stack.append((nx,ny))
    count = 0
    for i in range(n):
        for j in range(len(grid[i])):
            if grid[i][j]==1 and not visited[i][j]:
                dfs(i,j)
                count+=1
    return count

