def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Handles empty input and non‑iterable inputs gracefully.
    """
    # Guard against None or non‑iterable inputs
    if not nums:
        return 0
    try:
        iterator = iter(nums)
    except TypeError:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subseq of length i+1
    for x in iterator:
        # Only integers are expected; if something else appears, skip it
        try:
            # Ensure x is comparable
            i = bisect.bisect_left(tails, x)
        except Exception:
            continue
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

