def solve(grid):
    if not grid:
        return 0
    rows=len(grid)
    visited=set()
    def dfs(i,j):
        stack=[(i,j)]
        while stack:
            x,y=stack.pop()
            if (x,y) in visited:
                continue
            visited.add((x,y))
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx,ny=x+dx,y+dy
                if 0<=nx<rows and 0<=ny<len(grid[nx]) and grid[nx][ny]==1 and (nx,ny) not in visited:
                    stack.append((nx,ny))
    count=0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j]==1 and (i,j) not in visited:
                dfs(i,j)
                count+=1
    return count

